=head2 Google::Cloud::Dataform::V1::Dataform::ReleaseConfig

Represents a Dataform release configuration.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The release config's name.

=item * C<< $msg->git_commitish() >> / C<< $msg->git_commitish($value) >>

Type: C<String>

Required. Git commit/tag/branch name at which the repository should be
compiled. Must exist in the remote repository. Examples:
- a commit SHA: `12ade345`
- a tag: `tag1`
- a branch name: `branch1`

=item * C<< $msg->code_compilation_config() >> / C<< $msg->code_compilation_config($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::CodeCompilationConfig>)

Optional. If set, fields of `code_compilation_config` override the default
compilation settings that are specified in dataform.json.

=item * C<< $msg->cron_schedule() >> / C<< $msg->cron_schedule($value) >>

Type: C<String>

Optional. Optional schedule (in cron format) for automatic creation of
compilation results.

=item * C<< $msg->time_zone() >> / C<< $msg->time_zone($value) >>

Type: C<String>

Optional. Specifies the time zone to be used when interpreting
cron_schedule. Must be a time zone name from the [time zone
database](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones). If
left unspecified, the default is `UTC`.

=item * C<< $msg->recent_scheduled_release_records() >> / C<< $msg->recent_scheduled_release_records($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::ReleaseConfig::ScheduledReleaseRecord>)

Output only. Records of the 10 most recent scheduled release attempts,
ordered in descending order of `release_time`. Updated whenever automatic
creation of a compilation result is triggered by cron_schedule.

=item * C<< $msg->release_compilation_result() >> / C<< $msg->release_compilation_result($value) >>

Type: C<String>

Optional. The name of the currently released compilation result for this
release config. This value is updated when a compilation result is
automatically created from this release config (using cron_schedule), or
when this resource is updated by API call (perhaps to roll back to an
earlier release). The compilation result must have been created using this
release config. Must be in the format
`projects/*/locations/*/repositories/*/compilationResults/*`.

=item * C<< $msg->disabled() >> / C<< $msg->disabled($value) >>

Type: C<Bool>

Optional. Disables automatic creation of compilation results.

=item * C<< $msg->internal_metadata() >> / C<< $msg->internal_metadata($value) >>

Type: C<String>

Output only. All the metadata information that is used internally to serve
the resource. For example: timestamps, flags, status fields, etc. The
format of this field is a JSON string.

=back

