- a commit SHA: `12ade345`
- a tag: `tag1`
- a branch name: `branch1`

=item * C<< $msg->workspace() >> / C<< $msg->workspace($value) >>

Type: C<String>

Immutable. The name of the workspace to compile. Must be in the format
`projects/*/locations/*/repositories/*/workspaces/*`.

