Type: C<String>

Immutable. The name of the release config to compile. Must be in the
format `projects/*/locations/*/repositories/*/releaseConfigs/*`.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The compilation result's name.

=item * C<< $msg->code_compilation_config() >> / C<< $msg->code_compilation_config($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::CodeCompilationConfig>)

Immutable. If set, fields of `code_compilation_config` override the default
compilation settings that are specified in dataform.json.

=item * C<< $msg->resolved_git_commit_sha() >> / C<< $msg->resolved_git_commit_sha($value) >>

Type: C<String>

Output only. The fully resolved Git commit SHA of the code that was
compiled. Not set for compilation results whose source is a workspace.

=item * C<< $msg->dataform_core_version() >> / C<< $msg->dataform_core_version($value) >>

Type: C<String>

Output only. The version of `@dataform/core` that was used for compilation.

=item * C<< $msg->compilation_errors() >> / C<< $msg->compilation_errors($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::CompilationResult::CompilationError>)

Output only. Errors encountered during project compilation.

=item * C<< $msg->data_encryption_state() >> / C<< $msg->data_encryption_state($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::DataEncryptionState>)

Output only. Only set if the repository has a KMS Key.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp of when the compilation result was created.

