Type: C<String>

Output only. All the metadata information that is used internally to serve
the resource. For example: timestamps, flags, status fields, etc. The
format of this field is a JSON string.

=item * C<< $msg->private_resource_metadata() >> / C<< $msg->private_resource_metadata($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::PrivateResourceMetadata>)

Output only. Metadata indicating whether this resource is user-scoped.
