from a workspace.

=item * C<< $msg->gcs_repository_snapshot_metadata() >> / C<< $msg->gcs_repository_snapshot_metadata($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::GcsRepositorySnapshotMetadata>)

