Type: C<String>

Optional. The suffix that should be appended to all database (Google Cloud
project ID) names.

=item * C<< $msg->schema_suffix() >> / C<< $msg->schema_suffix($value) >>

Type: C<String>

Optional. The suffix that should be appended to all schema (BigQuery
dataset ID) names.

=item * C<< $msg->table_prefix() >> / C<< $msg->table_prefix($value) >>

Type: C<String>

Optional. The prefix that should be prepended to all table names.

=item * C<< $msg->builtin_assertion_name_prefix() >> / C<< $msg->builtin_assertion_name_prefix($value) >>

Type: C<String>

