=head2 Google::Cloud::Dataform::V1::Dataform::WorkflowConfig

Represents a Dataform workflow configuration.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The workflow config's name.

=item * C<< $msg->release_config() >> / C<< $msg->release_config($value) >>

Type: C<String>

Required. The name of the release config whose release_compilation_result
should be executed. Must be in the format
`projects/*/locations/*/repositories/*/releaseConfigs/*`.

=item * C<< $msg->invocation_config() >> / C<< $msg->invocation_config($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::InvocationConfig>)

Optional. If left unset, a default InvocationConfig will be used.

=item * C<< $msg->cron_schedule() >> / C<< $msg->cron_schedule($value) >>

Type: C<String>

Optional. Optional schedule (in cron format) for automatic execution of
this workflow config.

=item * C<< $msg->time_zone() >> / C<< $msg->time_zone($value) >>

Type: C<String>

Optional. Specifies the time zone to be used when interpreting
cron_schedule. Must be a time zone name from the [time zone
database](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones). If
left unspecified, the default is `UTC`.

=item * C<< $msg->recent_scheduled_execution_records() >> / C<< $msg->recent_scheduled_execution_records($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::WorkflowConfig::ScheduledExecutionRecord>)

Output only. Records of the 10 most recent scheduled execution attempts,
ordered in descending order of `execution_time`. Updated whenever automatic
creation of a workflow invocation is triggered by cron_schedule.

=item * C<< $msg->disabled() >> / C<< $msg->disabled($value) >>

Type: C<Bool>

Optional. Disables automatic creation of workflow invocations.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp of when the WorkflowConfig was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp of when the WorkflowConfig was last updated.

=item * C<< $msg->internal_metadata() >> / C<< $msg->internal_metadata($value) >>

Type: C<String>

Output only. All the metadata information that is used internally to serve
the resource. For example: timestamps, flags, status fields, etc. The
format of this field is a JSON string.

=back

=head2 Google::Cloud::Dataform::V1::Dataform::InvocationConfig

Includes various configuration options for a workflow invocation.
If both `included_targets` and `included_tags` are unset, all actions
will be included.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->included_targets() >> / C<< $msg->included_targets($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::Target>)

Optional. The set of action identifiers to include.

=item * C<< $msg->included_tags() >> / C<< $msg->included_tags($value) >>

Type: C<String>

Optional. The set of tags to include.

=item * C<< $msg->transitive_dependencies_included() >> / C<< $msg->transitive_dependencies_included($value) >>

Type: C<Bool>

Optional. When set to true, transitive dependencies of included actions
will be executed.

=item * C<< $msg->transitive_dependents_included() >> / C<< $msg->transitive_dependents_included($value) >>

Type: C<Bool>

Optional. When set to true, transitive dependents of included actions will
be executed.

=item * C<< $msg->fully_refresh_incremental_tables_enabled() >> / C<< $msg->fully_refresh_incremental_tables_enabled($value) >>

Type: C<Bool>

Optional. When set to true, any incremental tables will be fully refreshed.

=item * C<< $msg->service_account() >> / C<< $msg->service_account($value) >>

Type: C<String>

Optional. The service account to run workflow invocations under.

=item * C<< $msg->end_user_auth_config() >> / C<< $msg->end_user_auth_config($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::InvocationConfig::EndUserAuthenticationConfig>)

Optional. Configuration for end user authentication.
Do not set if `service_account` is used.

=item * C<< $msg->query_priority() >> / C<< $msg->query_priority($value) >>

Type: C<Enum> (L<Google::Cloud::Dataform::V1::InvocationConfig::QueryPriority>)

Optional. Specifies the priority for query execution in BigQuery.
More information can be found at
https://cloud.google.com/bigquery/docs/running-queries#queries.

=item * C<< $msg->concurrent_actions_limit() >> / C<< $msg->concurrent_actions_limit($value) >>

Type: C<Int32>

Optional. Maximum number of actions that can be executed concurrently.

=item * C<< $msg->execution_mode() >> / C<< $msg->execution_mode($value) >>

Type: C<Enum> (L<Google::Cloud::Dataform::V1::InvocationConfig::ExecutionMode>)

Optional. Specifies the execution mode for the workflow invocation.

=back

=head3 Enum: InvocationConfig::QueryPriority

=over 4

