=item * C<INTERACTIVE> => C<1>

=item * C<BATCH> => C<2>

=back

=head3 Enum: InvocationConfig::ExecutionMode

=over 4

=item * C<EXECUTION_MODE_UNSPECIFIED> => C<0>

=item * C<DEFAULT> => C<1>

=item * C<ALL_EXCEPT_UNIT_TESTS> => C<2>

=item * C<UNIT_TESTS_ONLY> => C<3>

=back

