`projects/*/locations/*/repositories/*/compilationResults/*`.

=item * C<< $msg->workflow_config() >> / C<< $msg->workflow_config($value) >>

Type: C<String>

Immutable. The name of the workflow config to invoke. Must be in the
format `projects/*/locations/*/repositories/*/workflowConfigs/*`.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The workflow invocation's name.

=item * C<< $msg->invocation_config() >> / C<< $msg->invocation_config($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::InvocationConfig>)

Immutable. If left unset, a default InvocationConfig will be used.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Dataform::V1::WorkflowInvocation::State>)

Output only. This workflow invocation's current state.

=item * C<< $msg->invocation_timing() >> / C<< $msg->invocation_timing($value) >>

Type: C<Message> (L<Google::Type::Interval::Interval>)

Output only. This workflow invocation's timing details.

=item * C<< $msg->resolved_compilation_result() >> / C<< $msg->resolved_compilation_result($value) >>

Type: C<String>

Output only. The resolved compilation result that was used to create this
invocation. Will be in the format
`projects/*/locations/*/repositories/*/compilationResults/*`.

=item * C<< $msg->data_encryption_state() >> / C<< $msg->data_encryption_state($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::DataEncryptionState>)

Output only. Only set if the repository has a KMS Key.

=item * C<< $msg->internal_metadata() >> / C<< $msg->internal_metadata($value) >>

Type: C<String>

Output only. All the metadata information that is used internally to serve
the resource. For example: timestamps, flags, status fields, etc. The
format of this field is a JSON string.

=item * C<< $msg->private_resource_metadata() >> / C<< $msg->private_resource_metadata($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::PrivateResourceMetadata>)

Output only. Metadata indicating whether this resource is user-scoped.
`WorkflowInvocation` resource is `user_scoped` only if it is sourced
from a compilation result and the compilation result is user-scoped.

=item * C<< $msg->pipeline_config() >> / C<< $msg->pipeline_config($value) >>

Type: C<Message> (L<Google::Cloud::Dataform::V1::Dataform::PipelineConfig>)

